       const [productResult,optionResult,inventoryResult,eventResult,priorEventResult,orderResult,accountingOrderResult,etsySalesResult,adjustmentResult,purchaseResult]=await Promise.all([adminProductRows(),window.beadSupabase.from('product_options').select('product_id,product_option_values(label,price_delta,sku,inventory_sku,inventory_units,quantity,unit_type)').order('sort_order'),window.beadSupabase.from('inventory_skus').select('sku,name,variant_name,quantity_on_hand,cost,price,unit_type,preferred_vendor,category'),eventQuery(start,end),eventQuery(previousStart,previousEnd),fetchAllRows(researchOrderQuery),fetchAllRows(orderQuery),fetchAllRows(etsySalesQuery),fetchAllRows(adjustmentQuery),fetchAllRows(purchaseQuery)]);
