   panel.innerHTML='<div class="admin-heading"><div><p class="kicker">STORE PERFORMANCE</p><h2>Metrics</h2><p>Accounting metrics are separate from product research. Website sales, Etsy sales, and combined totals use the selected period.</p></div></div><section class="admin-card" id="accounting-metrics"></section><section class="admin-card metrics-controls"><div class="admin-form-grid"><label>Reporting period<select data-metrics-period><option value="week" '+(selectedPeriod==='week'?'selected':'')+'>Last 7 days</option><option value="month" '+(selectedPeriod==='month'?'selected':'')+'>This month</option><option value="year" '+(selectedPeriod==='year'?'selected':'')+'>This year</option><option value="all" '+(selectedPeriod==='all'?'selected':'')+'>All time</option></select></label><label>Find in research report<input type="search" data-metrics-search placeholder="SKU, name, category, vendor, or search term"></label></div><div class="metrics-filter-list" role="group" aria-label="Research metric filters">'+filterButtons+'</div></section><section class="admin-card" id="metrics-report"></section>';
