   const drawAccounting=()=>{const combined=accountingRows.find((row)=>row.channel==='Combined')||{};const value=(row,key)=>key==='netSales'||key==='netProfit'?money(row[key]):['grossSales','discounts','refunds','shippingCollected','cogs','shrinkage','marketplaceFees','taxCollected','inventoryPurchases'].includes(key)?money(row[key]):Number(row[key]||0);const accountingCells=(row)=>[row.channel,row.orders,row.unitsSold,row.returnedUnits,value(row,'grossSales'),value(row,'discounts'),row.promoUnits,value(row,'refunds'),value(row,'netSales'),value(row,'shippingCollected'),value(row,'cogs'),value(row,'shrinkage'),value(row,'marketplaceFees'),value(row,'taxCollected'),value(row,'inventoryPurchases'),value(row,'netProfit'),row.salesYoy,row.cogsYoy,row.netProfitYoy];accounting.innerHTML='<div class="admin-heading"><div><h3>Business accounting · '+periodLabel+'</h3><p>Website and Etsy are isolated, with combined totals last. Net profit includes product sales, shipping collected, COGS, marketplace fees, and shrinkage. Carrier shipping expense is not connected yet.</p></div><button type="button" data-download-accounting>Export accounting CSV</button></div><div class="admin-stat-grid"><div class="admin-stat-card"><b>'+money(combined.netSales)+'</b><span>Combined net product sales</span></div><div class="admin-stat-card"><b>'+money(combined.cogs)+'</b><span>Combined COGS</span></div><div class="admin-stat-card"><b>'+money(combined.shrinkage)+'</b><span>Inventory shrinkage</span></div><div class="admin-stat-card"><b>'+money(combined.netProfit)+'</b><span>Net profit after COGS</span></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr>'+accountingHeaders.map((header)=>'<th>'+header+'</th>').join('')+'</tr></thead><tbody>'+accountingRows.map((row)=>'<tr>'+accountingCells(row).map((cell)=>'<td>'+adminSafe(cell)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';accounting.querySelector('[data-download-accounting]').onclick=()=>download([accountingHeaders,...accountingRows.map(accountingCells)],'business-accounting-'+selectedPeriod+'.csv');};
