    const redrawSorted=()=>{report.dataset.sort=sort.value;const sorted=sortedRows();const currentPage=Math.min(Number(report.dataset.page||1),Math.max(1,Math.ceil(sorted.length/pageSize)));report.dataset.page=currentPage;report.querySelector('tbody').innerHTML=sorted.slice((currentPage-1)*pageSize,currentPage*pageSize).map(sortCell).join('')||'<tr><td colspan="'+headers.length+'">No matching SKU data.</td></tr>';report.querySelector('.admin-pagination span').textContent='Page '+currentPage+' of '+Math.max(1,Math.ceil(sorted.length/pageSize))+' · '+sorted.length+' rows';report.querySelector('[data-metrics-page="prev"]').disabled=currentPage===1;report.querySelector('[data-metrics-page="next"]').disabled=currentPage===Math.max(1,Math.ceil(sorted.length/pageSize));};
    sort.onchange=redrawSorted;
