const captureAdminProductEdit=(form)=>({productId:form.dataset.productId,category:form.elements.category_slug?.value||'',variants:[...form.querySelectorAll('[data-variant-row]')].map((row)=>({label:row.querySelector('[data-variant-label]')?.value||'',sku:row.querySelector('[data-variant-sku]')?.value||'',weight_value:row.querySelector('[data-variant-weight]')?.value||'',weight_unit:row.querySelector('[data-variant-weight-unit]')?.value||'',cost:row.querySelector('[data-variant-cost]')?.value||'',price:row.querySelector('[data-variant-price]')?.value||'',preferred_vendor:row.querySelector('[data-variant-vendor]')?.value||''})),mappings:[...form.querySelectorAll('[data-etsy-row]')].map((row)=>({etsy_sku:row.querySelector('[data-etsy-sku]')?.value||'',inventory_sku:row.querySelector('[data-etsy-inventory-sku]')?.value||'',inventory_units:row.querySelector('[data-etsy-inventory-units]')?.value||''}))});
const parseAdminProductEdit=(fields)=>{let options=[];let mappings=[];try{options=JSON.parse(fields.sku_data||'[]');}catch(error){options=[];}try{mappings=JSON.parse(fields.etsy_mappings||'[]');}catch(error){mappings=[];}return{category:fields.category_slug||'',variants:(options||[]).flatMap((option)=>option.values||[]),mappings:mappings||[]};};
const recordAdminProductChanges=async(snapshot,fields)=>{if(!snapshot.productId||!window.beadSupabase)return;const next=parseAdminProductEdit(fields);const entries=[];const addEntry=(inventorySku,fieldName,previousValue,newValue)=>{const previous=adminHistoryValue(previousValue);const nextValue=adminHistoryValue(newValue);if(previous===nextValue)return;entries.push({product_id:snapshot.productId,inventory_sku:adminHistoryValue(inventorySku),field_name:fieldName,previous_value:previous,new_value:nextValue,change_type:previous===null?'added':nextValue===null?'removed':'updated',note:'Product page edit'});};addEntry(null,'Category',snapshot.category,next.category);const usedVariants=new Set();next.variants.forEach((variant,index)=>{const oldVariant=snapshot.variants.find((candidate,candidateIndex)=>!usedVariants.has(candidateIndex)&&adminHistoryValue(candidate.sku)===adminHistoryValue(variant.sku))||snapshot.variants.find((candidate,candidateIndex)=>!usedVariants.has(candidateIndex)&&adminHistoryValue(candidate.label)===adminHistoryValue(variant.label))||(snapshot.variants.length===next.variants.length?snapshot.variants[index]:null);if(oldVariant){const oldIndex=snapshot.variants.indexOf(oldVariant);usedVariants.add(oldIndex);}const inventorySku=adminHistoryValue(variant.sku)||adminHistoryValue(oldVariant?.sku);addEntry(inventorySku,'SKU',oldVariant?.sku,variant.sku);if(oldVariant){addEntry(inventorySku,'Weight',adminHistoryWeight(oldVariant),adminHistoryWeight(variant));addEntry(inventorySku,'Cost',oldVariant.cost,variant.cost);addEntry(inventorySku,'Price',oldVariant.price,variant.price);addEntry(inventorySku,'Preferred vendor',oldVariant.preferred_vendor,variant.preferred_vendor);}else{addEntry(inventorySku,'Weight',null,adminHistoryWeight(variant));addEntry(inventorySku,'Cost',null,variant.cost);addEntry(inventorySku,'Price',null,variant.price);addEntry(inventorySku,'Preferred vendor',null,variant.preferred_vendor);}});snapshot.variants.forEach((variant,index)=>{if(usedVariants.has(index))return;addEntry(variant.sku,'SKU',variant.sku,null);});const mappingCount=Math.max(snapshot.mappings.length,next.mappings.length);for(let index=0;index<mappingCount;index+=1)addEntry(next.mappings[index]?.inventory_sku||snapshot.mappings[index]?.inventory_sku,'Etsy mapping SKU',adminHistoryMapping(snapshot.mappings[index]),adminHistoryMapping(next.mappings[index]));if(!entries.length)return;const result=await window.beadSupabase.from('product_change_history').insert(entries);if(result.error)console.warn('Unable to record product change history.',result.error);};
document.addEventListener('submit',(event)=>{const form=event.target;if(!(form instanceof HTMLFormElement)||!form.matches('.admin-item-form')||!form.dataset.productId)return;const snapshot=captureAdminProductEdit(form);const fields=Object.fromEntries(new FormData(form));const waitForSave=async(attempt=0)=>{if(form.isConnected){if(attempt<80)window.setTimeout(()=>void waitForSave(attempt+1),100);return;}if(panel.querySelector('.admin-empty'))return;await recordAdminProductChanges(snapshot,fields);};window.setTimeout(()=>void waitForSave(),100);},true);
const saveAdminBundleRecipes=async(productId,fields)=>{let rows=[];try{rows=JSON.parse(fields.bundle_components||'[]');if(!Array.isArray(rows))throw new Error('Bundle recipes are invalid.');}catch(error){throw new Error('Bundle recipes are invalid: '+error.message);}const normalizedRows=rows.map((row)=>({bundleSku:String(row.bundle_sku||'').trim(),componentSku:String(row.component_sku||'').trim(),quantity:Number(row.quantity)})).filter((row)=>row.bundleSku||row.componentSku);if(normalizedRows.some((row)=>!row.bundleSku||!row.componentSku||!Number.isInteger(row.quantity)||row.quantity<1))throw new Error('Each bundle component needs a bundle SKU, component SKU, and whole-number quantity.');if(normalizedRows.some((row)=>row.bundleSku.toLowerCase()===row.componentSku.toLowerCase()))throw new Error('A bundle cannot use itself as a component.');const allSkus=[...new Set(normalizedRows.flatMap((row)=>[row.bundleSku,row.componentSku]))];if(!allSkus.length)return;const lookup=await cloudAdmin().from('inventory_skus').select('id,sku').in('sku',allSkus);if(lookup.error)adminFailure(lookup.error);const idBySku=new Map((lookup.data||[]).map((row)=>[row.sku.toLowerCase(),row.id]));const missingBundles=[...new Set(normalizedRows.map((row)=>row.bundleSku).filter((sku)=>!idBySku.has(sku.toLowerCase())))];if(missingBundles.length){const created=await cloudAdmin().from('inventory_skus').upsert(missingBundles.map((sku)=>({sku,name:String(fields.name||sku).trim(),variant_name:sku,quantity_on_hand:0,reorder_point:0,item_type:'Non-inventory',category:String(fields.category_slug||'').trim()||null,taxable:true,unit_type:'Each',source_system:'admin'})),{onConflict:'sku'}).select('id,sku');if(created.error)adminFailure(created.error);(created.data||[]).forEach((row)=>idBySku.set(row.sku.toLowerCase(),row.id));}if(normalizedRows.some((row)=>!idBySku.has(row.componentSku.toLowerCase())))throw new Error('Every component SKU must already exist in canonical inventory.');const bundleIds=[...new Set(normalizedRows.map((row)=>idBySku.get(row.bundleSku.toLowerCase())).filter(Boolean))];const remove=await cloudAdmin().from('inventory_bundle_components').delete().in('bundle_sku_id',bundleIds);if(remove.error)adminFailure(remove.error);const unique=new Set();const inserts=normalizedRows.map((row,index)=>({bundle_sku_id:idBySku.get(row.bundleSku.toLowerCase()),component_sku_id:idBySku.get(row.componentSku.toLowerCase()),bundle_sku:row.bundleSku,component_sku:row.componentSku,quantity:row.quantity,sort_order:index})).filter((row)=>{const key=row.bundle_sku_id+'|'+row.component_sku_id;if(unique.has(key))return false;unique.add(key);return true;});if(inserts.length){const result=await cloudAdmin().from('inventory_bundle_components').insert(inserts);if(result.error)adminFailure(result.error);}};
const saveAdminEtsyMappings=async(productId,fields)=>{let mappings=[];try{mappings=JSON.parse(fields.etsy_mappings||'[]');if(!Array.isArray(mappings))throw new Error('Etsy mappings are invalid.');}catch(error){throw new Error('Etsy mappings are invalid: '+error.message);}const rows=mappings.map((mapping,index)=>({etsySku:String(mapping.etsy_sku||'').trim(),components:(mapping.components||[]).map((component)=>({inventorySku:String(component.inventory_sku||'').trim(),units:Number(component.inventory_units)})).filter((component)=>component.inventorySku),active:mapping.active!==false,sortOrder:index})).filter((mapping)=>mapping.etsySku);if(!rows.length)return;if(rows.some((mapping)=>!mapping.components.length||mapping.components.some((component)=>!Number.isInteger(component.units)||component.units<1)))throw new Error('Each Etsy mapping needs at least one inventory component and a whole-number quantity.');const skus=[...new Set(rows.flatMap((mapping)=>mapping.components.map((component)=>component.inventorySku)))];const lookup=await cloudAdmin().from('inventory_skus').select('id,sku').in('sku',skus);if(lookup.error)adminFailure(lookup.error);const idBySku=new Map((lookup.data||[]).map((row)=>[row.sku.toLowerCase(),row.id]));if(rows.some((mapping)=>mapping.components.some((component)=>!idBySku.has(component.inventorySku.toLowerCase()))))throw new Error('Every Etsy mapping component SKU must exist in canonical inventory.');const base=await cloudAdmin().from('product_etsy_mappings').insert(rows.map((mapping)=>({product_id:productId,etsy_sku:mapping.etsySku,inventory_sku:mapping.components[0].inventorySku,inventory_sku_id:idBySku.get(mapping.components[0].inventorySku.toLowerCase()),inventory_units:mapping.components[0].units,active:mapping.active,sort_order:mapping.sortOrder}))).select('id,etsy_sku');if(base.error)adminFailure(base.error);const mappingIds=new Map((base.data||[]).map((mapping)=>[mapping.etsy_sku.toLowerCase(),mapping.id]));const components=rows.flatMap((mapping)=>mapping.components.map((component,index)=>({mapping_id:mappingIds.get(mapping.etsySku.toLowerCase()),inventory_sku_id:idBySku.get(component.inventorySku.toLowerCase()),inventory_sku:component.inventorySku,inventory_units:component.units,sort_order:index}))).filter((component)=>component.mapping_id);if(components.length){const result=await cloudAdmin().from('product_etsy_mapping_components').insert(components);if(result.error)adminFailure(result.error);}};
