const renderExpenses=async()=>{if(activeTab!=='expenses')return;if(!window.beadSupabase){panel.innerHTML='<div class="product-unavailable"><h2>Expenses require the connected store database.</h2><p>Sign in to the admin account connected to Supabase to record business expenses and reconciliations.</p></div>';return;}const [expenseResult,reconciliationResult,orderRows]=await Promise.all([fetchAdminRowsAll(()=>cloudAdmin().from('business_expenses').select('id,expense_date,vendor,category,amount,notes,receipt_path,receipt_name,created_at').order('expense_date',{ascending:false})),fetchAdminRowsAll(()=>cloudAdmin().from('business_bank_reconciliations').select('id,period_month,starting_balance,ending_balance,notes,reconciled_at,updated_at').order('period_month',{ascending:false})),fetchAdminRowsAll(()=>cloudAdmin().from('orders').select('id,total,status,created_at').order('created_at',{ascending:false}))]);if(activeTab!=='expenses')return;if(expenseResult?.error||reconciliationResult?.error||orderRows?.error){panel.innerHTML='<div class="admin-empty">Unable to load expenses and reconciliation records.</div>';return;}const expenses=expenseResult||[];const reconciliations=reconciliationResult||[];const orders=orderRows||[];const today=new Date();let selectedMonth=today.toISOString().slice(0,7);const currentUser=await cloudAdmin().auth.getUser();const userId=currentUser.data?.user?.id||null;const signedReceiptUrls=new Map();for(const expense of expenses){if(!expense.receipt_path)continue;const signed=await cloudAdmin().storage.from('expense-receipts').createSignedUrl(expense.receipt_path,3600);if(!signed.error&&signed.data?.signedUrl)signedReceiptUrls.set(expense.id,signed.data.signedUrl);}const monthLabel=(month)=>{const date=new Date(month+'-01T00:00:00');return Number.isNaN(date.getTime())?month:date.toLocaleDateString(undefined,{month:'long',year:'numeric'});};const monthSales=(month)=>orders.filter((order)=>order.created_at?.slice(0,7)===month&&!['cancelled','refunded'].includes(String(order.status||'').toLowerCase())).reduce((total,order)=>total+Number(order.total||0),0);const monthExpenses=(month)=>expenses.filter((expense)=>String(expense.expense_date||'').slice(0,7)===month).reduce((total,expense)=>total+Number(expense.amount||0),0);const reconciliationFor=(month)=>reconciliations.find((entry)=>String(entry.period_month||'').slice(0,7)===month);const recentMonths=[...new Set([selectedMonth,...reconciliations.map((entry)=>String(entry.period_month||'').slice(0,7)).filter(Boolean)])].sort().reverse().slice(0,12);const draw=()=>{const selected=reconciliationFor(selectedMonth);const visibleExpenses=expenses.slice(0,25);const expenseRows=visibleExpenses.map((expense)=>{const receipt=signedReceiptUrls.get(expense.id);return'<tr><td>'+adminSafe(expense.expense_date)+'</td><td>'+adminSafe(expense.category||'Other')+'</td><td>'+adminSafe(expense.vendor)+'</td><td>'+adminSafe(expense.notes||'—')+'</td><td>$'+Number(expense.amount||0).toFixed(2)+'</td><td>'+(receipt?'<a href="'+adminSafe(receipt)+'" target="_blank" rel="noreferrer">'+adminSafe(expense.receipt_name||'View receipt')+'</a>':'—')+'</td><td><button type="button" data-delete-expense="'+adminSafe(expense.id)+'">Delete</button></td></tr>';}).join('')||'<tr><td colspan="7">No expenses recorded yet.</td></tr>';const recentRows=recentMonths.map((month)=>{const entry=reconciliationFor(month);const starting=entry?Number(entry.starting_balance||0):null;const sales=monthSales(month);const spent=monthExpenses(month);const expected=starting===null?null:starting+sales-spent;const ending=entry&&entry.ending_balance!==null&&entry.ending_balance!==undefined?Number(entry.ending_balance):null;const difference=ending===null||expected===null?null:ending-expected;return'<tr><td>'+adminSafe(monthLabel(month))+'</td><td>'+(starting===null?'—':'$'+starting.toFixed(2))+'</td><td>$'+sales.toFixed(2)+'</td><td>$'+spent.toFixed(2)+'</td><td>'+(expected===null?'—':'$'+expected.toFixed(2))+'</td><td>'+(ending===null?'—':'$'+ending.toFixed(2))+'</td><td>'+(difference===null?'Open':'$'+difference.toFixed(2))+'</td><td>'+(entry?.reconciled_at?'Reconciled':'Open')+'</td></tr>';}).join('')||'<tr><td colspan="8">No monthly reconciliations yet.</td></tr>';panel.innerHTML='<div class="admin-heading"><div><p class="kicker">BUSINESS OPERATIONS</p><h2>Expenses</h2><p>Record business expenses with vendor notes and private receipt copies. Expense totals flow into Metrics and stay separate from inventory purchases.</p></div></div><section class="admin-card"><h3>Add expense</h3><form class="admin-form" data-expense-form><div class="admin-form-grid"><label>Date<input name="expense_date" type="date" required value="'+adminSafe(today.toISOString().slice(0,10))+'"></label><label>Category<select name="category"><option selected>Other</option><option>Website fees</option><option>Insurance</option><option>Office supplies</option><option>Advertising &amp; marketing</option><option>Software &amp; subscriptions</option><option>Shipping &amp; postage</option><option>Equipment</option><option>Professional services</option><option>Taxes &amp; licenses</option><option>Utilities</option></select></label><label>Vendor<input name="vendor" required placeholder="Vendor name"></label><label>Amount<input name="amount" type="number" min="0" step="0.01" required placeholder="0.00"></label><label>Receipt copy<input name="receipt" type="file" accept="image/*,.pdf,application/pdf"></label></div><label>Notes<textarea name="notes" rows="3" placeholder="What was purchased or why was it paid?"></textarea><small>Receipt files are private and available only to admins. Maximum size: 10 MB.</small><div class="admin-actions"><button type="submit" class="cta">Save expense</button></div><p data-expense-status role="status"></p></form></section><section class="admin-card"><div class="admin-heading"><div><h3>Monthly bank reconciliation</h3><p>Enter the bank starting and ending balances. Expected ending balance equals starting balance plus recorded order totals minus recorded expenses.</p></div></div><form class="admin-form" data-reconciliation-form><div class="admin-form-grid"><label>Month<input name="period_month" type="month" required value="'+adminSafe(selectedMonth)+'"></label><label>Starting bank balance<input name="starting_balance" type="number" min="0" step="0.01" required value="'+(selected?Number(selected.starting_balance||0).toFixed(2):'')+'"></label><label>Actual ending bank balance<input name="ending_balance" type="number" min="0" step="0.01" value="'+(selected?.ending_balance===null||selected?.ending_balance===undefined?'':Number(selected.ending_balance).toFixed(2))+'"></label></div><label>Reconciliation notes<textarea name="notes" rows="3" placeholder="Explain any difference or leave a note for the accountant.">'+adminSafe(selected?.notes||'')+'</textarea><div class="admin-actions"><button type="submit" class="cta">Save reconciliation</button></div><p data-reconciliation-status role="status"></p></form><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Month</th><th>Starting</th><th>Recorded sales</th><th>Expenses</th><th>Expected ending</th><th>Actual ending</th><th>Difference</th><th>Status</th></tr></thead><tbody>'+recentRows+'</tbody></table></div></section><section class="admin-card"><div class="admin-heading"><div><h3>Expense ledger</h3><p>Most recent 25 expenses. Export the complete ledger for accounting.</p></div><button type="button" data-download-expenses>Export expenses CSV</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Date</th><th>Category</th><th>Vendor</th><th>Notes</th><th>Amount</th><th>Receipt</th><th></th></tr></thead><tbody>'+expenseRows+'</tbody></table></div></section>';const expenseForm=panel.querySelector('[data-expense-form]');expenseForm.addEventListener('submit',async(event)=>{event.preventDefault();const fields=Object.fromEntries(new FormData(expenseForm));const status=expenseForm.querySelector('[data-expense-status]');const amount=Number(fields.amount);const file=expenseForm.querySelector('[name="receipt"]').files?.[0];if(!fields.vendor.trim()||!Number.isFinite(amount)||amount<0){status.textContent='Enter a vendor and a non-negative amount.';return;}if(file&&file.size>10*1024*1024){status.textContent='Receipt files must be 10 MB or smaller.';return;}status.textContent='Saving expense…';let receiptPath=null;try{if(file){const safeName=file.name.toLowerCase().replace(/[^a-z0-9._-]+/g,'-')||'receipt';receiptPath=(userId||'admin')+'/'+Date.now()+'-'+safeName;const upload=await cloudAdmin().storage.from('expense-receipts').upload(receiptPath,file,{upsert:false,contentType:file.type||undefined});if(upload.error)throw upload.error;}const result=await cloudAdmin().from('business_expenses').insert({expense_date:fields.expense_date,vendor:fields.vendor.trim(),category:fields.category?.trim()||'Other',amount,notes:fields.notes?.trim()||null,receipt_path:receiptPath,receipt_name:file?.name||null,created_by:userId}).select('id').single();if(result.error)throw result.error;await renderExpenses();}catch(error){if(receiptPath)await cloudAdmin().storage.from('expense-receipts').remove([receiptPath]);status.textContent='Expense was not saved: '+error.message;}});panel.querySelector('[data-reconciliation-form]').addEventListener('submit',async(event)=>{event.preventDefault();const form=event.currentTarget;const fields=Object.fromEntries(new FormData(form));const status=form.querySelector('[data-reconciliation-status]');const starting=Number(fields.starting_balance);const ending=String(fields.ending_balance||'').trim()===''?null:Number(fields.ending_balance);if(!/^\d{4}-\d{2}$/.test(fields.period_month)||!Number.isFinite(starting)||starting<0||(ending!==null&&(!Number.isFinite(ending)||ending<0))){status.textContent='Enter a valid month and non-negative balances.';return;}status.textContent='Saving reconciliation…';const result=await cloudAdmin().from('business_bank_reconciliations').upsert({period_month:fields.period_month+'-01',starting_balance:starting,ending_balance:ending,notes:fields.notes?.trim()||null,reconciled_at:ending===null?null:new Date().toISOString(),created_by:userId,updated_at:new Date().toISOString()},{onConflict:'period_month'});if(result.error){status.textContent='Reconciliation was not saved: '+result.error.message;return;}selectedMonth=fields.period_month;await renderExpenses();});panel.querySelector('[name="period_month"]').addEventListener('change',(event)=>{selectedMonth=event.target.value;draw();});panel.querySelector('[data-download-expenses]').onclick=()=>expenseCsvDownload([['Date','Category','Vendor','Amount','Notes','Receipt file','Created at'],...expenses.map((expense)=>[expense.expense_date,expense.category||'Other',expense.vendor,expense.amount,expense.notes||'',expense.receipt_name||'',expense.created_at||''])],'business-expenses.csv');panel.querySelectorAll('[data-delete-expense]').forEach((button)=>button.addEventListener('click',async()=>{if(!window.confirm('Delete this expense and its receipt copy?'))return;button.disabled=true;const expense=expenses.find((entry)=>entry.id===button.dataset.deleteExpense);const result=await cloudAdmin().from('business_expenses').delete().eq('id',button.dataset.deleteExpense);if(result.error){button.disabled=false;panel.querySelector('[data-expense-status]').textContent='Expense was not deleted: '+result.error.message;return;}if(expense?.receipt_path)await cloudAdmin().storage.from('expense-receipts').remove([expense.receipt_path]);await renderExpenses();}));draw();};};
const baseRenderStatsWithExpenses=renderStats;renderStats=async function(){await baseRenderStatsWithExpenses();if(activeTab!=='stats'||!window.beadSupabase)return;const period=panel.dataset.metricsPeriod||'month';const expenseRows=await fetchAdminRowsAll(()=>cloudAdmin().from('business_expenses').select('expense_date,amount,vendor,notes,receipt_name').order('expense_date',{ascending:false}));if(!Array.isArray(expenseRows)||activeTab!=='stats')return;const total=expenseRows.filter((expense)=>expenseDateInPeriod(expense.expense_date,period)).reduce((sum,expense)=>sum+Number(expense.amount||0),0);const accounting=panel.querySelector('#accounting-metrics');const grid=accounting?.querySelector('.admin-stat-grid');if(!grid||grid.querySelector('[data-expense-metric]'))return;const makeCard=(label,value)=>{const card=document.createElement('div');card.className='admin-stat-card';card.dataset.expenseMetric='true';card.innerHTML='<b>$'+value.toFixed(2)+'</b><span>'+label+'</span>';return card;};grid.append(makeCard('Business expenses',total));const netCard=[...grid.querySelectorAll('.admin-stat-card')].find((card)=>card.textContent.includes('Net profit after COGS'));const netAfterCogs=Number((netCard?.querySelector('b')?.textContent||'').replace(/[^0-9.-]/g,''))||0;grid.append(makeCard('Net profit after expenses',netAfterCogs-total));const heading=accounting.querySelector('.admin-heading');const button=document.createElement('button');button.type='button';button.textContent='Open expenses';button.onclick=()=>{activeTab='expenses';document.querySelectorAll('[data-admin-tab]').forEach((tab)=>tab.classList.toggle('active',tab.dataset.adminTab==='expenses'));void renderExpenses();};heading?.append(button);};
const expensesTab=document.createElement('button');expensesTab.className='admin-tab';expensesTab.dataset.adminTab='expenses';expensesTab.textContent='Expenses';document.querySelector('.admin-sidebar nav').append(expensesTab);expensesTab.addEventListener('click',()=>{activeTab='expenses';document.querySelectorAll('[data-admin-tab]').forEach((tab)=>tab.classList.toggle('active',tab.dataset.adminTab==='expenses'));void renderExpenses();});
const baseRenderStatsWithGross=renderStats;renderStats=async function(){await baseRenderStatsWithGross();if(activeTab!=='stats')return;const accounting=panel.querySelector('#accounting-metrics');const summary=accounting?.querySelector('.admin-stat-grid .admin-stat-card');const combinedRow=accounting?.querySelector('.admin-table tbody tr:last-child');if(!summary||!combinedRow)return;const grossCell=combinedRow.cells[4];if(grossCell)summary.querySelector('b').textContent=grossCell.textContent;summary.querySelector('span').textContent='Combined gross product sales';};
const baseRenderStatsWithExpenseBreakdown=renderStats;renderStats=async function(){await baseRenderStatsWithExpenseBreakdown();if(activeTab!=='stats'||!window.beadSupabase)return;const accounting=panel.querySelector('#accounting-metrics');if(!accounting||accounting.dataset.expenseBreakdown==='true')return;let expenseRows;try{expenseRows=await fetchAdminRowsAll(()=>cloudAdmin().from('business_expenses').select('expense_date,category,vendor,amount').order('expense_date',{ascending:false}));}catch(error){return;}if(activeTab!=='stats'||!Array.isArray(expenseRows))return;const inPeriod=expenseRows.filter((expense)=>expenseDateInPeriod(expense.expense_date,panel.dataset.metricsPeriod||'month'));const total=inPeriod.reduce((sum,expense)=>sum+Number(expense.amount||0),0);const by=(key)=>{const totals=new Map();inPeriod.forEach((expense)=>{const label=String(expense[key]||'Other').trim()||'Other';totals.set(label,(totals.get(label)||0)+(Number(expense.amount)||0));});return [...totals.entries()].sort((left,right)=>right[1]-left[1]);};const moneyValue=(value)=>'$'+Number(value||0).toFixed(2);const accountingTable=accounting.querySelector('table');const headerRow=accountingTable?.querySelector('thead tr');const bodyRows=[...(accountingTable?.querySelectorAll('tbody tr')||[])];if(!headerRow||!bodyRows.length)return;['Business expenses','Net profit after expenses'].forEach((header)=>{const cell=document.createElement('th');cell.textContent=header;headerRow.append(cell);});const moneyFromCell=(cell)=>Number(String(cell?.textContent||'').replace(/[^0-9.-]/g,''))||0;const combinedRow=bodyRows.find((row)=>String(row.cells[0]?.textContent||'').trim()==='Combined');bodyRows.forEach((row)=>{const expenseCell=document.createElement('td');const netCell=document.createElement('td');const isCombined=row===combinedRow;const netAfterCogs=moneyFromCell(row.cells[15]);expenseCell.textContent=isCombined?moneyValue(total):'—';netCell.textContent=isCombined?moneyValue(netAfterCogs-total):'—';row.append(expenseCell,netCell);});const headingNote=accounting.querySelector('.admin-heading p');if(headingNote)headingNote.textContent='Website and Etsy are isolated, with combined totals last. Business expenses are categorized and assigned to the combined result; net profit after expenses subtracts them after COGS, shrinkage, and marketplace fees.';const downloadButton=accounting.querySelector('[data-download-accounting]');if(downloadButton)downloadButton.onclick=()=>{const csvRows=[[...headerRow.cells].map((cell)=>cell.textContent),...bodyRows.map((row)=>[...row.cells].map((cell)=>cell.textContent))];const escape=(value)=>'"'+String(value??'').replace(/"/g,'""')+'"';const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csvRows.map((row)=>row.map(escape).join(',')).join('\n')],{type:'text/csv;charset=utf-8'}));link.download='business-accounting-'+(panel.dataset.metricsPeriod||'month')+'.csv';link.click();URL.revokeObjectURL(link.href);};const breakdown=document.createElement('section');breakdown.className='admin-expense-breakdown';breakdown.innerHTML='<div><h4>Expense breakdown · '+(panel.dataset.metricsPeriod||'month')+'</h4><p>Business expenses are grouped by the category and vendor entered on the expense ledger.</p></div>';const breakdownGrid=document.createElement('div');breakdownGrid.className='admin-expense-breakdown-grid';const makeBreakdownTable=(title,rows)=>{const wrap=document.createElement('div');wrap.className='admin-table-wrap';const table=document.createElement('table');table.className='admin-table';table.innerHTML='<caption>'+title+'</caption><thead><tr><th>Name</th><th>Total</th></tr></thead><tbody></tbody>';const body=table.querySelector('tbody');if(rows.length)rows.forEach(([label,value])=>{const row=document.createElement('tr');const name=document.createElement('td');const amount=document.createElement('td');name.textContent=label;amount.textContent=moneyValue(value);row.append(name,amount);body.append(row);});else body.innerHTML='<tr><td colspan="2">No expenses in this period.</td></tr>';wrap.append(table);return wrap;};breakdownGrid.append(makeBreakdownTable('By category',by('category')),makeBreakdownTable('By vendor',by('vendor')));breakdown.append(breakdownGrid);accounting.append(breakdown);accounting.dataset.expenseBreakdown='true';};
